// Build the chart query from two independent selections, each remembered in
// flow context so either dropdown (or the Refresh button) can trigger a reload.
//
//   range     : 7 / 15 / 30 / 90 days, or "all"
//   averaging : N consecutive readings per plotted point (1 = raw)
//
// Averaging is by row count, not by time bucket, so widening the range does not
// coarsen the trace - it only adds points.

const RANGES = ["1", "2", "7", "15", "30", "90", "all"];
const in_ = String(msg.payload === undefined ? "" : msg.payload);

if (in_.indexOf("avg:") === 0) {
    const n = parseInt(in_.slice(4), 10);
    if (!isNaN(n) && n > 0) { flow.set("avgN", n); }
}
else if (RANGES.indexOf(in_) !== -1) {
    flow.set("range", in_);
}
// anything else (the Refresh button) just reuses what is stored

const range = flow.get("range") || "7";
const N = flow.get("avgN") || 5;

const where = (range === "all")
    ? ""
    : " where timestamp >= strftime('%s','now') - " + (parseInt(range, 10) * 86400);

const COLS = "humidity, temperature, conductivity, PH, N, P, K";

let sql;
if (N === 1) {
    sql = "select timestamp, " + COLS + " from NPKv1" + where + " order by timestamp;";
}
else {
    // group consecutive readings into blocks of N
    sql =
        "with r as (select timestamp, " + COLS + "," +
        " (row_number() over (order by timestamp) - 1)/" + N + " as g" +
        " from NPKv1" + where + ")" +
        " select cast(avg(timestamp) as integer) as timestamp," +
        " avg(humidity) as humidity, avg(temperature) as temperature," +
        " avg(conductivity) as conductivity, avg(PH) as PH," +
        " avg(N) as N, avg(P) as P, avg(K) as K, count(*) as n_raw" +
        " from r group by g order by timestamp;";
}

msg.topic = sql;

const rangeLabel = function (r) {
    if (r === "all") { return "all data"; }
    if (r === "1")   { return "last 24 h"; }
    return "last " + r + " days";
};
const rangeTxt = rangeLabel(range);
flow.set("lastSql", sql);
flow.set("lastDesc", rangeTxt + ", avg of " + N);

node.status({ fill: "blue", shape: "dot",
              text: rangeTxt + ", avg of " + N });
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const N = flow.get("avgN") || 5;
const range = flow.get("range") || "7";
const rangeTxt = (range === "all") ? "all data"
    : (range === "1") ? "last 24 h" : "last " + range + "d";

if (rows.length === 0) {
    msg.payload = "no data in " + rangeTxt;
    node.status({ fill: "yellow", shape: "ring", text: "0 points" });
    return msg;
}

// short form: 08-15 13:20
const fmt = function (secs) {
    return new Date(secs * 1000).toISOString().slice(5, 16).replace("T", " ");
};

let readings = 0;
for (const r of rows) { readings += (r.n_raw || 1); }

const pts = rows.length;
const total = pts * 6;

msg.payload =
    pts.toLocaleString() + " pts/chart · " +
    (N > 1 ? "avg " + N : "raw") + " · " +
    readings.toLocaleString() + " readings\n" +
    fmt(rows[0].timestamp) + " → " + fmt(rows[rows.length - 1].timestamp);

if (total > 20000) {
    msg.payload += " · heavy (" + total.toLocaleString() + " on screen)";
    node.status({ fill: "red", shape: "dot", text: pts + " x6 = " + total });
} else {
    node.status({ fill: "green", shape: "dot", text: pts + " x6 = " + total });
}
return msg;

// Turn dashboard input into a console command for the SoilNode.
//
// Every correction is applied in the microcontroller: NpkCal computes
//
//     value = A * raw + B
//
// per channel, where "raw" is whatever the probe reports. The probe is left in
// its factory state deliberately, so it stays a stable input and its own
// constants never enter the arithmetic.
//
// This is why the layer split is gone. The probe can only offset temperature,
// humidity, EC and pH (0x0050-0x0053) and only gives N/P/K a gain; the ESP32
// applies both terms to all seven channels, so pH gets a real two-point span
// correction against buffers 4.00/7.00, which the probe could not do.
//
// Commands go out as plain text: NpkConsole::jsonToLine has no mapping for the
// "sensor" family, and handleMqtt only parses JSON when the payload starts '{'.

const in_ = msg.payload;
const s = (in_ === undefined || in_ === null) ? "" : String(in_);

if (s.indexOf("ch:") === 0) {
    flow.set("calChannel", s.slice(3));
    return null;
}

if (s.indexOf("act:") !== 0) {
    const n = Number(s.replace(",", "."));      // accept 7.00 and 7,00
    if (!isNaN(n)) { flow.set("calRef", n); }
    return null;
}

const act = s.slice(4);
const ch = flow.get("calChannel") || "";
const ref = flow.get("calRef");

const fail = function (why) {
    node.status({ fill: "red", shape: "ring", text: why });
    return [null, { payload: { line: "cannot send: " + why, kind: "error" } }];
};

const needsChannel = (act !== "resetall" && act !== "sensor" && act !== "list");
if (needsChannel && !ch) { return fail("choose a channel first"); }

const needsRef = (act === "1p" || act === "low" || act === "high");
if (needsRef && (ref === undefined || ref === null || isNaN(ref))) {
    return fail("enter a reference value first");
}

const r = String(ref);
let line = "";
let note = "";

if (act === "low" || act === "high") {
    line = "cal " + act + " " + ch + " " + r;
    note = "two-point step, solved and stored in the ESP32";
} else if (act === "1p") {
    line = "cal 1p " + ch + " " + r;
    note = "offset-only trim, keeps the current gain";
} else if (act === "sensor") {
    line = "sensor";
    note = "read-only: the probe's own registers, left at factory values";
} else if (act === "list") {
    line = "cal";
    note = "the coefficients in use";
} else if (act === "reset") {
    line = "cal clear " + ch;
    note = "back to A=1, B=0 for this channel";
} else if (act === "resetall") {
    line = "cal clear all";
    note = "back to A=1, B=0 on every channel";
} else {
    return fail("unknown action " + act);
}

node.status({ fill: "blue", shape: "dot", text: line });

return [
    { topic: "NPKcommand", payload: line },
    { payload: { line: "> " + line + "\n  (" + note + ")", kind: "sent" } }
];

// Rolling log of commands sent and replies received.
// Replies are multi-line fixed-width text from the firmware console
// (see NpkConsole::listCalibration), so they are shown verbatim in a <pre>.

const MAX_LINES = 120;

let entry, kind;
if (msg.payload && typeof msg.payload === "object" && msg.payload.line !== undefined) {
    entry = msg.payload.line;              // from the command builder
    kind = msg.payload.kind || "sent";
} else {
    entry = String(msg.payload).replace(/\r/g, "");   // reply from the node
    kind = "reply";
}

const stamp = new Date().toTimeString().slice(0, 8);

let lines = flow.get("calLog") || [];
for (const raw of entry.split("\n")) {
    if (raw.trim() === "" && kind === "reply") { continue; }
    lines.push({ t: stamp, k: kind, s: raw });
}
if (lines.length > MAX_LINES) { lines = lines.slice(lines.length - MAX_LINES); }
flow.set("calLog", lines);

const esc = function (s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
};
const colour = { sent: "#1565c0", reply: "#222", error: "#b71c1c" };

// newest first, so the latest reply is visible without scrolling
const html = lines.slice().reverse().map(function (l) {
    return '<div style="color:' + (colour[l.k] || "#222") + '">' +
           '<span style="opacity:.55">' + l.t + '</span>  ' + esc(l.s) + '</div>';
}).join("");

msg.payload = '<pre style="margin:0;font-size:12px;line-height:1.35;' +
              'white-space:pre-wrap;word-break:break-word">' + html + '</pre>';
node.status({ fill: "grey", shape: "dot", text: lines.length + " lines" });
return msg;

// NPKstatus is retained: "online" or "sensor-unreachable" (SoilNode.ino).
const s = String(msg.payload);
const stamp = new Date().toTimeString().slice(0, 8);

if (s === "online") {
    msg.payload = "sensor online · " + stamp;
    node.status({ fill: "green", shape: "dot", text: "online" });
} else if (s === "sensor-unreachable") {
    msg.payload = "SENSOR UNREACHABLE · " + stamp;
    node.status({ fill: "red", shape: "dot", text: "unreachable" });
} else {
    msg.payload = s + " · " + stamp;
    node.status({ fill: "grey", shape: "dot", text: s });
}
return msg;

// Backup / restore controller.
//
//   act:backup   ask the node for its register dump and arm the parser
//   act:restore  read the OLDEST snapshot and replay it onto the probe
//   act:backups  list what has been captured
//
// outputs: [ MQTT command, SQLite query, console log ]

const s = String(msg.payload === undefined ? "" : msg.payload);

if (s === "act:backup") {
    // the parser only stores a dump that was asked for here, so pressing
    // "Read probe registers" on its own never creates a snapshot
    flow.set("pendingBackup", Date.now());
    node.status({ fill: "blue", shape: "dot", text: "awaiting dump" });
    return [
        { topic: "NPKcommand", payload: "sensor" },
        null,
        { payload: { line: "> sensor  (capturing a backup)", kind: "sent" } }
    ];
}

if (s === "act:restore") {
    // oldest first: the earliest snapshot is the closest thing to factory
    flow.set("restoreMode", "apply");
    return [null,
        { topic: "select * from probe_cal_backup order by ts limit 1;" },
        { payload: { line: "> reading the oldest backup", kind: "sent" } }];
}

if (s === "act:backups") {
    flow.set("restoreMode", "list");
    return [null,
        { topic: "select ts, ts_utc, note from probe_cal_backup order by ts;" },
        { payload: { line: "> listing backups", kind: "sent" } }];
}

return null;

// Parse the "sensor" register dump into a snapshot row.
//
// Runs only when a backup was requested (flow.pendingBackup), so a manual
// "Read probe registers" press does not silently create snapshots.
//
// Lines look like:
//   0x0050  temperature offset   raw      0  -> 0.00
//   0x04E8  n factor 0.00000   offset 0
//   0x0022  conductivity factor       0   factory default 0
// Classified by register number rather than by wording, which is sturdier.

const NL = String.fromCharCode(10);
const text = String(msg.payload);

if (text.indexOf("Sensor-side calibration") === -1) { return null; }   // not a dump

const asked = flow.get("pendingBackup");
if (!asked) { return null; }
flow.set("pendingBackup", null);

const OFFSETS = { "0X0050": "temp", "0X0051": "hum", "0X0052": "ec", "0X0053": "ph" };
const NUTRIENTS = { "0X04E8": "n", "0X04F2": "p", "0X04FC": "k" };
const READONLY = { "0X0022": "ec_factor", "0X0023": "salinity_factor", "0X0024": "tds_factor" };

const snap = { offsets: {}, factors: {}, nutrient_offsets: {}, readonly: {}, unread: [] };

const lines = text.split(NL);
for (const raw of lines) {
    const t = raw.trim().split(/ +/);
    if (!t.length || t[0].substring(0, 2).toUpperCase() !== "0X") { continue; }
    const reg = t[0].toUpperCase();

    if (raw.indexOf("no reply") !== -1) { snap.unread.push(reg); continue; }

    if (OFFSETS[reg] !== undefined) {
        const i = t.indexOf("raw");
        const v = Number(t[i + 1]);
        if (i !== -1 && !isNaN(v)) { snap.offsets[OFFSETS[reg]] = v; }
    } else if (NUTRIENTS[reg] !== undefined) {
        const key = NUTRIENTS[reg];
        const fi = t.indexOf("factor");
        const oi = t.indexOf("offset");
        const f = Number(t[fi + 1]);
        const o = Number(t[oi + 1]);
        if (fi !== -1 && !isNaN(f)) { snap.factors[key] = f; }
        if (oi !== -1 && !isNaN(o)) { snap.nutrient_offsets[key] = o; }
    } else if (READONLY[reg] !== undefined) {
        const v = Number(t[t.indexOf("factor") + 1]);
        if (!isNaN(v)) { snap.readonly[READONLY[reg]] = v; }
    }
}

const nFactors = Object.keys(snap.factors).length;
const nOffsets = Object.keys(snap.offsets).length;
if (nFactors === 0 && nOffsets === 0) {
    return [null, { payload: { line: "backup aborted: nothing parsed from the dump",
                               kind: "error" } }];
}

const now = new Date();
const note = nFactors + " factors, " + nOffsets + " offsets" +
             (snap.unread.length ? ", " + snap.unread.length + " unread" : "");

msg.params = {
    $ts: Math.floor(now.getTime() / 1000),
    $ts_utc: now.toISOString().slice(0, 19).replace("T", " "),
    $note: note,
    $data: JSON.stringify(snap)
};

node.status({ fill: "green", shape: "dot", text: "saved: " + note });

return [msg, { payload: { line: "backup saved (" + note + "): " +
                                 JSON.stringify(snap.factors) + " " +
                                 JSON.stringify(snap.offsets), kind: "sent" } }];

// Turn a stored snapshot back into write commands, or list what exists.
// outputs: [ commands (rate limited), console log ]

const NL = String.fromCharCode(10);
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const mode = flow.get("restoreMode") || "list";

if (rows.length === 0) {
    return [null, { payload: { line: "no backups stored yet - press Backup probe registers first",
                               kind: "error" } }];
}

if (mode === "list") {
    const lines = rows.map(function (r) { return "  " + r.ts_utc + "   " + r.note; });
    return [null, { payload: { line: "backups on record:" + NL + lines.join(NL),
                               kind: "reply" } }];
}

let snap;
try { snap = JSON.parse(rows[0].data); }
catch (e) {
    return [null, { payload: { line: "backup is unreadable: " + e.message, kind: "error" } }];
}

const cmds = [];
const warn = [];

// gains: sensor factor <n|p|k> <float>
for (const key of ["n", "p", "k"]) {
    const v = snap.factors ? snap.factors[key] : undefined;
    if (v === undefined || v === null || isNaN(v)) { continue; }
    cmds.push("sensor factor " + key + " " + v);
    if (v === 0) {
        warn.push("note: " + key + " gain in this backup is 0, which is what the probe " +
                  "shipped with - a two-point solve cannot run until it is set to 1.0");
    }
}

// offsets: sensor offset <temp|hum|ec|ph> <int>
for (const key of ["temp", "hum", "ec", "ph"]) {
    const v = snap.offsets ? snap.offsets[key] : undefined;
    if (v === undefined || v === null || isNaN(v)) { continue; }
    cmds.push("sensor offset " + key + " " + Math.round(v));
}

if (cmds.length === 0) {
    return [null, { payload: { line: "backup holds nothing writable", kind: "error" } }];
}

// no write command exists for these, so say so rather than pretending
const skipped = [];
if (snap.nutrient_offsets && Object.keys(snap.nutrient_offsets).length) {
    skipped.push("N/P/K offset registers");
}
if (snap.readonly && Object.keys(snap.readonly).length) {
    skipped.push("0x0022-0x0024 (EC/salinity/TDS factors)");
}

let summary = "restoring " + rows[0].ts_utc + ":" + NL + "  " + cmds.join(NL + "  ");
if (skipped.length) {
    summary += NL + "not restorable (no write command in the firmware): " + skipped.join(", ");
}
if (warn.length) { summary += NL + warn.join(NL); }

node.status({ fill: "blue", shape: "dot", text: cmds.length + " commands" });

// one message per command; the delay node paces them so each Modbus write
// finishes before the next arrives
const out = cmds.map(function (c) { return { topic: "NPKcommand", payload: c }; });
return [out, { payload: { line: summary, kind: "sent" } }];

// Replay the query the charts last ran, so the CSV matches the plot exactly
// (same range, same averaging). Falls back to the stored selection, then to
// the 7-day default, so the endpoint works even on a fresh restart.

let sql = flow.get("lastSql");
let desc = flow.get("lastDesc");

if (!sql) {
    const range = flow.get("range") || "7";
    const N = flow.get("avgN") || 5;
    const where = (range === "all") ? ""
        : " where timestamp >= strftime('%s','now') - " + (parseInt(range, 10) * 86400);
    const COLS = "humidity, temperature, conductivity, PH, N, P, K";
    if (N === 1) {
        sql = "select timestamp, " + COLS + " from NPKv1" + where + " order by timestamp;";
    } else {
        sql = "with r as (select timestamp, " + COLS + "," +
              " (row_number() over (order by timestamp) - 1)/" + N + " as g" +
              " from NPKv1" + where + ")" +
              " select cast(avg(timestamp) as integer) as timestamp," +
              " avg(humidity) as humidity, avg(temperature) as temperature," +
              " avg(conductivity) as conductivity, avg(PH) as PH," +
              " avg(N) as N, avg(P) as P, avg(K) as K, count(*) as n_raw" +
              " from r group by g order by timestamp;";
    }
    desc = (range === "all") ? "all data" : "last " + range + " days, avg of " + N;
}

msg.topic = sql;
msg.desc = desc;
node.status({ fill: "blue", shape: "dot", text: desc || "default" });
return msg;

// Turn the query result into a CSV download.
//
// timestamp is stored as unix seconds; the file carries both the epoch value
// and a readable UTC column so it opens sensibly in a spreadsheet without
// anyone having to convert anything.

const rows = Array.isArray(msg.payload) ? msg.payload : [];

const COLS = ["timestamp", "utc", "humidity", "temperature", "conductivity",
              "PH", "N", "P", "K", "n_raw"];

const esc = function (v) {
    if (v === null || v === undefined) { return ""; }
    // averaging leaves float noise like 24.119999999999997 - 3 decimals is
    // far beyond the probe's resolution and keeps the file readable
    if (typeof v === "number" && !Number.isInteger(v)) { v = Number(v.toFixed(3)); }
    const s = String(v);
    // quote anything that would confuse a CSV parser
    return (s.indexOf(",") !== -1 || s.indexOf('"') !== -1 || s.indexOf("\n") !== -1)
        ? '"' + s.replace(/"/g, '""') + '"'
        : s;
};

const NL = String.fromCharCode(13) + String.fromCharCode(10);   // CRLF for Excel
const out = [COLS.join(",")];

for (const r of rows) {
    const utc = (r.timestamp === null || r.timestamp === undefined)
        ? "" : new Date(r.timestamp * 1000).toISOString().slice(0, 19).replace("T", " ");
    out.push(COLS.map(function (c) {
        if (c === "utc") { return esc(utc); }
        return esc(r[c]);
    }).join(","));
}

const stamp = new Date().toISOString().slice(0, 16).replace("T", "_").replace(":", "");
const slug = String(msg.desc || "export").replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "");
const filename = "npk_" + slug + "_" + stamp + ".csv";

msg.payload = out.join(NL) + NL;
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": 'attachment; filename="' + filename + '"',
};
msg.statusCode = 200;

node.status({ fill: "green", shape: "dot", text: rows.length + " rows" });
return msg;
